function hkt(s19: number) : string {
    let jn: string = "" // string vazia
    for (let i : number = 0; i < s19; i =  i + 7) {
        if (i == 0 && i % 2 == 0) {
            jn = jn + "hansode." 
        } else if (i % 2 == 0 && i < 7) {
            jn = jn + "wota."
        } else if (i > 7 && i < 15) {
            jn = jn + "tenshi."
        }
    }

    return jn
}
